using GraphApi.Models.ENC.Preguntas;namespace GraphApi.Services.ENC.Preguntas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Preguntas.    /// </summary>    public interface IPreguntasService    {        /// <summary>        /// Obtiene la lista de Preguntas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadPreguntas>> GetPreguntas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Preguntas con filtros opcionales.        /// </summary>        /// <param name="preguntaID">Filtro opcional para PreguntaID.</param>        /// <param name="encuestaID">Filtro opcional para EncuestaID.</param>        /// <param name="texto">Filtro opcional para Texto.</param>        /// <param name="tipoPreguntaID">Filtro opcional para TipoPreguntaID.</param>        /// <param name="orden">Filtro opcional para Orden.</param>        /// <param name="requerida">Filtro opcional para Requerida.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetPreguntasDynamic(            int? preguntaID,            int? encuestaID,            string? texto,            int? tipoPreguntaID,            int? orden,            bool? requerida,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Pregunta.        /// </summary>        /// <param name="objInput">Datos para crear el Pregunta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPreguntas> CreatePreguntas(            clCreatePreguntas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Pregunta.        /// </summary>        /// <param name="objInput">Datos para actualizar el Pregunta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPreguntas?> UpdatePreguntas(            clUpdatePreguntas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Pregunta por su ID.        /// </summary>        /// <param name="nPreguntasID">ID del Pregunta a eliminar.</param>        Task<bool> DeletePreguntas(int nPreguntasID);    }}